import java.util.*;

class Solution {
    public int popLanterns(int[] vals) {
        int n = vals.length + 2;
        int[] v = new int[n];
        v[0] = 1; v[n - 1] = 1;                        // virtual neighbours of brightness 1
        for (int i = 0; i < vals.length; i++) v[i + 1] = vals[i];
        int[][] dp = new int[n][n];                    // dp[l][r]: lanterns strictly between l and r
        for (int gap = 2; gap < n; gap++) {
            for (int l = 0; l + gap < n; l++) {
                int r = l + gap, best = 0;
                for (int k = l + 1; k < r; k++) {      // k is popped last in (l, r)
                    best = Math.max(best, dp[l][k] + dp[k][r] + v[l] * v[k] * v[r]);
                }
                dp[l][r] = best;
            }
        }
        return dp[0][n - 1];
    }
}

