class Solution:
    def popLanterns(self, vals: List[int]) -> int:
        v = [1] + vals + [1]
        n = len(v)
        dp = [[0] * n for _ in range(n)]
        for gap in range(2, n):
            for l in range(n - gap):
                r = l + gap
                vl, vr = v[l], v[r]
                row_l, best = dp[l], 0
                for k in range(l + 1, r):
                    c = row_l[k] + dp[k][r] + vl * v[k] * vr
                    if c > best: best = c
                row_l[r] = best
        return dp[0][n - 1]

