function popLanterns(vals) {
  const v = [1, ...vals, 1], n = v.length;
  const memo = Array.from({length: n}, () => new Array(n).fill(-1));
  function go(l, r) {
    if (r - l < 2) return 0;
    if (memo[l][r] >= 0) return memo[l][r];
    let best = 0;
    for (let k = l + 1; k < r; k++) best = Math.max(best, go(l, k) + go(k, r) + v[l] * v[k] * v[r]);
    return memo[l][r] = best;
  }
  return go(0, n - 1);
}
